oxy_webhelp_navlinks = {"arch_prepare_gcp_arch_loc-d39536e8837":{"topics":[{"title":"GCP archival locations with immutable storage","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> automatically applies object-level immutability to all data         archived to GCP buckets on Rubrik clusters running CDM version 9.6.0 or later. No user         configuration is required.<\/p>","href":"archival\/gcp_arch_loc_immu_storage.html","attributes":{"data-id":"gcp_arch_loc_immu_storage"},"menu":{"hasChildren":false},"tocID":"gcp_arch_loc_immu_storage-d39536e8848","topics":[]},{"title":"GCP archive tiering","shortdesc":"<p class=\"shortdesc\">Rubrik CDM supports tiering to the GCP Archive storage class by configuring lifecycle         rules in the GCP console. The Archive storage class cannot be selected directly when         creating a GCP archival location in <span class=\"ph\">RSC<\/span>.<\/p>","href":"gcp\/gcp_archive_tiering.html","attributes":{"data-id":"gcp_archive_tiering"},"menu":{"hasChildren":false},"tocID":"gcp_archive_tiering-d39536e8861","topics":[]},{"title":"Archive preparation in GCP","shortdesc":"<p class=\"shortdesc\">Preparing a GCP bucket for archiving requires creating a service account and enabling         object versioning and object lock on the bucket for clusters running CDM version 9.6 or         later.<\/p>","href":"gcp\/gcp_archive_prep.html","attributes":{"data-id":"gcp_archive_prep"},"menu":{"hasChildren":false},"tocID":"gcp_archive_prep-d39536e8875","topics":[]},{"title":"GCS storage classes","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports four GCS storage classes when creating an archival         location to meet different storage requirements.<\/p>","href":"gcp\/gcs_storage_classes.html","attributes":{"data-id":"gcs_storage_classes"},"menu":{"hasChildren":false},"tocID":"gcs_storage_classes-d39536e8886","topics":[]}]}};